# A well-known maximal triangle-free graph is the complete bipartite graph K_{n/2, n/2}
# For 12 vertices, K_{6,6} is triangle-free (bipartite) and maximal
# (adding any edge within the same partition creates... wait, bipartite graphs have no odd cycles,
# but adding an edge within a partition: does it create a triangle?
# In K_{6,6}, every vertex in partition A is connected to ALL vertices in partition B.
# If we add edge (u,v) where u,v are both in partition A:
# u and v both connect to all of B, so u-w-v forms a triangle for any w in B. YES, triangle created.
# So K_{6,6} is indeed maximal triangle-free.

# Let's construct K_{6,6} with partitions {0,1,2,3,4,5} and {6,7,8,9,10,11}

edges = []
for u in range(6):
    for v in range(6, 12):
        edges.append((u, v))

print(f"Number of edges: {len(edges)}")
print("Edges:", edges)

# Verify: triangle-free (bipartite graphs are triangle-free)
# Verify: maximal (adding any edge within partition creates triangle)
import itertools

# Check triangle-free
def has_triangle(edges, n):
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    for i in range(n):
        for j in range(i+1, n):
            if adj[i][j]:
                for k in range(j+1, n):
                    if adj[i][k] and adj[j][k]:
                        return True, (i,j,k)
    return False, None

result, tri = has_triangle(edges, 12)
print(f"Has triangle: {result}, {tri}")

# Check maximality: for every non-edge, adding it creates a triangle
edge_set = set(edges)
non_edges = []
for u in range(12):
    for v in range(u+1, 12):
        if (u,v) not in edge_set:
            non_edges.append((u,v))

print(f"Number of non-edges: {len(non_edges)}")

all_maximal = True
for u, v in non_edges:
    test_edges = edges + [(u,v)]
    result, tri = has_triangle(test_edges, 12)
    if not result:
        print(f"Adding edge ({u},{v}) does NOT create a triangle - not maximal!")
        all_maximal = False

print(f"Is maximal: {all_maximal}")
